CREATE OR REPLACE FUNCTION public.caixa_transferir(p_origem uuid,p_destino uuid,p_data date,p_valor numeric,p_descricao text) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tid uuid:=gen_random_uuid(); BEGIN IF NOT public.has_owner_access() THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('caixa:'||auth.uid()::text,0)); IF p_origem=p_destino OR p_valor IS NULL OR p_valor<=0 OR p_data IS NULL OR round(p_valor,2)<>p_valor OR p_valor::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Informe contas diferentes, data e valor positivo.'; END IF; IF(SELECT count(*) FROM public.contas_caixa WHERE id IN(p_origem,p_destino) AND user_id=auth.uid() AND ativa)<>2 THEN RAISE EXCEPTION 'Selecione duas contas ativas da escola.'; END IF; INSERT INTO public.lancamentos(mes,data_lancamento,tipo,grupo,categoria,valor,descricao,origem,conta_id,data_pagamento,transferencia_id) VALUES(to_char(p_data,'YYYY-MM'),p_data,'saida','Transferências','Transferência entre contas',p_valor,p_descricao,'transferencia',p_origem,p_data,tid),(to_char(p_data,'YYYY-MM'),p_data,'entrada','Transferências','Transferência entre contas',p_valor,p_descricao,'transferencia',p_destino,p_data,tid); RETURN tid; END $$;
REVOKE ALL ON FUNCTION public.caixa_transferir(uuid,uuid,date,numeric,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.caixa_transferir(uuid,uuid,date,numeric,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.caixa_lock_conta() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('caixa:'||NEW.user_id::text,0)); RETURN NEW; END $$;
CREATE TRIGGER aaa_caixa_lock_conta BEFORE INSERT OR UPDATE ON public.contas_caixa FOR EACH ROW EXECUTE FUNCTION public.caixa_lock_conta();
COMMENT ON COLUMN public.contas_caixa.data_saldo_inicial IS 'Closing balance date. Only later payment dates contribute to the balance.';